import os
from pathlib import Path

# Inspect plausible project/secret locations without exposing unrelated file contents.
for base in ['/work','/inputs','/opt','/srv','/mnt','/run','/home']:
    matches=[]
    try:
        for root, dirs, files in os.walk(base):
            # avoid potentially large/cache trees
            dirs[:] = [d for d in dirs if d not in {'__pycache__'}]
            for name in files:
                low=name.lower()
                if any(term in low for term in ('shopify','secret','.env','toml','config')):
                    matches.append(os.path.join(root,name))
    except Exception as e:
        print(base, 'ERROR', repr(e))
        continue
    print(base, matches[:100])

